        .chart-caption { color: #666; font-size: 0.9em; margin-top: 10px; font-style: italic; }

        /* Tables */
        table { width: 100%; border-collapse: collapse; margin: 20px 0; }
        th { background: #1E3A5F; color: white; padding: 12px 15px; text-align: left; }
